/**
 * Core execution logic for smart_execute and design_agent tools.
 * Combines LLM code generation with sandbox execution, including retry-on-error.
 */
import { callLlm, extractCode } from './llmClient.js';
import { buildCodeGenPrompt, buildPlanPrompt } from './apiReference.js';
import { createAndRunSandbox } from './sandbox.js';
const MAX_CONTEXT_CHARS = 10_000;
/**
 * Generate code via LLM and execute it in the sandbox.
 * On error, retries once with error context added to the prompt.
 */
export async function executeSmartCode(description, options) {
    const start = Date.now();
    let llmDuration = 0;
    // Step 1: Generate code
    const prompt = buildCodeGenPrompt(description, options?.context);
    const llmResult = await callLlm(prompt, { backend: options?.backend });
    llmDuration += llmResult.durationMs;
    let code = extractCode(llmResult.text);
    // Step 2: Execute in sandbox
    let sandboxResult = await createAndRunSandbox(code);
    // Step 3: On error, retry once with error context
    let retried = false;
    if (sandboxResult.error) {
        retried = true;
        const retryPrompt = buildCodeGenPrompt(description, `${options?.context ? options.context + '\n\n' : ''}## Previous attempt failed
Code that failed:
${code}

Error:
${sandboxResult.error}

Fix the error and output corrected code. Do not repeat the same mistake.`);
        const retryLlm = await callLlm(retryPrompt, { backend: options?.backend });
        llmDuration += retryLlm.durationMs;
        code = extractCode(retryLlm.text);
        sandboxResult = await createAndRunSandbox(code);
    }
    return {
        result: sandboxResult.result,
        code,
        retried,
        logs: sandboxResult.logs,
        error: sandboxResult.error,
        duration: Date.now() - start,
        llmDuration,
    };
}
/**
 * Extract node IDs from a sandbox result value.
 */
function extractNodeIds(value) {
    const ids = [];
    if (value && typeof value === 'object') {
        const obj = value;
        if (typeof obj.id === 'string') {
            ids.push(obj.id);
        }
        if (Array.isArray(value)) {
            for (const item of value) {
                ids.push(...extractNodeIds(item));
            }
        }
    }
    return ids;
}
/**
 * Truncate context to stay within token budget.
 */
function truncateContext(context) {
    if (context.length <= MAX_CONTEXT_CHARS)
        return context;
    return context.slice(-MAX_CONTEXT_CHARS) + '\n...(earlier context truncated)';
}
/**
 * Multi-step design agent.
 * Plans steps via LLM, executes each, accumulates context, stops on double failure.
 */
export async function executeDesignAgent(description, options) {
    const start = Date.now();
    const steps = [];
    const nodeIds = [];
    let accumulatedContext = '';
    // Step 1: Plan
    const planPrompt = buildPlanPrompt(description);
    const planResult = await callLlm(planPrompt, { backend: options?.backend });
    const planText = extractCode(planResult.text);
    let stepDescriptions;
    try {
        stepDescriptions = JSON.parse(planText);
        if (!Array.isArray(stepDescriptions) || stepDescriptions.length === 0) {
            throw new Error('Expected non-empty array');
        }
    }
    catch {
        // If planning fails, fall back to single-step execution
        stepDescriptions = [description];
    }
    const totalSteps = stepDescriptions.length;
    let stoppedEarly = false;
    // Step 2: Execute each step
    for (let i = 0; i < stepDescriptions.length; i++) {
        const stepDesc = stepDescriptions[i];
        const stepStart = Date.now();
        const contextForStep = accumulatedContext
            ? `Step ${i + 1} of ${totalSteps}.\n\n${truncateContext(accumulatedContext)}`
            : `Step ${i + 1} of ${totalSteps}.`;
        const result = await executeSmartCode(stepDesc, {
            backend: options?.backend,
            context: contextForStep,
        });
        const step = {
            description: stepDesc,
            code: result.code,
            result: result.result,
            error: result.error,
            retried: result.retried,
            duration: Date.now() - stepStart,
        };
        steps.push(step);
        if (result.error) {
            // Double failure (already retried inside executeSmartCode) — stop
            stoppedEarly = true;
            break;
        }
        // Accumulate context for next steps
        const resultSummary = JSON.stringify(result.result, null, 2);
        accumulatedContext += `\n\nStep ${i + 1} completed: ${stepDesc}\nResult: ${resultSummary}`;
        // Collect node IDs
        nodeIds.push(...extractNodeIds(result.result));
    }
    return {
        steps,
        completedSteps: steps.filter(s => !s.error).length,
        totalSteps,
        stoppedEarly,
        nodeIds,
        duration: Date.now() - start,
    };
}
